PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment
       (AVG(xsd:decimal(?scenarioChange)) AS ?avgScenarioChange)
       (AVG(xsd:decimal(?goalProgress)) AS ?avgGoalProgress)
       (AVG(xsd:decimal(?volatility)) AS ?avgVolatility)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:segment ?segment . }
  BIND(COALESCE(?segment, "NULL") AS ?segment)

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?diff)) AS ?scenarioChange)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing ;
          wm:scenarioRebalancingOfInvestor ?investor ;
          wm:newAllocationPct ?newAlloc ;
          wm:currentAllocationPct ?currAlloc .
      BIND(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc) AS ?diff)
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?prog)) AS ?goalProgress) (AVG(xsd:decimal(?vol)) AS ?volatility)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor .
      OPTIONAL { ?goal wm:progressPct ?prog . }
      OPTIONAL { ?goal wm:avgVolatilityPct ?vol . }
    }
    GROUP BY ?investor
  }
}
GROUP BY ?segment

