      WHERE {
        ?investor rdf:type wm:Investor .
        ?investor wm:hasScenarioRebalancing ?sr .
        ?sr wm:currentAllocationPct ?cur .
        ?sr wm:newAllocationPct ?new .
        BIND((xsd:decimal(?new) - xsd:decimal(?cur)) AS ?scDiff)
      }
      GROUP BY ?investor
    }
  }

  # Rebalancing gap and amount per investor
  OPTIONAL {
    {
      SELECT ?investor (AVG(xsd:decimal(?gap)) AS ?rebalancingGap) (SUM(xsd:decimal(?amt)) AS ?rebalancingAmount)
      WHERE {
        ?investor rdf:type wm:Investor .
        ?investor wm:hasRebalancingAction ?ra .
        ?ra wm:currentAllocationPct ?c .
        ?ra wm:targetAllocationPct ?t .
        ?ra wm:amount ?amt .
        BIND((xsd:decimal(?t) - xsd:decimal(?c)) AS ?gap)
      }
      GROUP BY ?investor
    }
  }
}
GROUP BY ?segmentLabel

