PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  {
    SELECT ?investor (AVG(xsd:decimal(?vol)) AS ?avgVolatility) (AVG(xsd:decimal(?sharpe)) AS ?avgSharpe)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:avgVolatilityPct ?vol .
      ?goal wm:avgSharpeRatio ?sharpe .
    }
    GROUP BY ?investor
    HAVING (xsd:decimal(?avgVolatility) > 20 && xsd:decimal(?avgSharpe) < 0)
  }

  {
    SELECT ?investor (MAX(xsd:decimal(?risk)) AS ?riskScore)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:healthOfInvestor ?investor .
      ?ph wm:riskScore ?risk .
    }
    GROUP BY ?investor
    HAVING (xsd:decimal(?riskScore) > 50)
  }
}

