PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (SUM(?invScenarioCount) AS ?totalScenarios) (AVG(?invAvgGap) AS ?avgRebalancingGap) (AVG(?invAvgAmount) AS ?avgRebalancingAmount)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?gap)) AS ?invAvgGap) (COUNT(DISTINCT ?scenario) AS ?invScenarioCount)
    WHERE {
      ?investor wm:hasScenarioRebalancing ?sr .
      ?sr rdf:type wm:ScenarioRebalancing .
      OPTIONAL { ?sr wm:scenario ?scenario . }
      OPTIONAL { ?sr wm:currentAllocationPct ?curr . }
      OPTIONAL { ?sr wm:newAllocationPct ?new . }
      FILTER(BOUND(?curr) && BOUND(?new))
      BIND((xsd:decimal(?new) - xsd:decimal(?curr)) AS ?gap)
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?amount)) AS ?invAvgAmount)
    WHERE {
      ?investor wm:hasRebalancingAction ?ra .
      ?ra rdf:type wm:RebalancingAction .
      OPTIONAL { ?ra wm:amount ?amount . }
      FILTER(BOUND(?amount))
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskGroup (SUM(?holdingSum) AS ?totalHoldingPurchases2024) (SUM(?cashSum) AS ?totalCashFlow2024)
WHERE {
  ?inv rdf:type wm:Investor .
  OPTIONAL { ?inv wm:riskTolerance ?riskTol . }
  BIND(COALESCE(?riskTol, "NULL") AS ?riskGroup)

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?cost)) AS ?holdingSum)
    WHERE {
      ?h rdf:type wm:PortfolioHolding .
      ?h wm:heldByInvestor ?inv .
      ?h wm:cost ?cost .
      ?h wm:purchaseDate ?pdate .
      FILTER(STRSTARTS(STR(?pdate), "2024"))
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?cashSum)
    WHERE {
      ?c rdf:type wm:CashFlow .
      ?c wm:cashFlowOfInvestor ?inv .
      ?c wm:amount ?amount .
      ?c wm:date ?cdate .
      FILTER(STRSTARTS(STR(?cdate), "2024"))
    }
    GROUP BY ?inv
  }
}
GROUP BY ?riskGroup

