SELECT ?category
       (COALESCE(?rebTotal, 0) AS ?totalRebalanceAmount)
       (COALESCE(?cfTotal, 0) AS ?totalCashFlowAmount)
       (COALESCE(?cfCount, 0) AS ?totalTransactionCount)
WHERE {
  {
    SELECT ?category (SUM(xsd:decimal(?rebAmt)) AS ?rebTotal)
    WHERE {
      ?inv rdf:type wm:Investor .
      OPTIONAL { ?inv wm:category ?category . }
      ?reb rdf:type wm:RebalancingAction .
      ?reb wm:rebalancingActionOfInvestor ?inv .
      ?reb wm:amount ?rebAmt .
    }
    GROUP BY ?category
  }
  OPTIONAL {
    SELECT ?category (SUM(xsd:decimal(?cfAmt)) AS ?cfTotal) (COUNT(?cf) AS ?cfCount)
    WHERE {
      ?inv rdf:type wm:Investor .
      OPTIONAL { ?inv wm:category ?category . }
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?cf wm:amount ?cfAmt .
    }
    GROUP BY ?category
  }
}

