      BIND (xsd:decimal(?new) - xsd:decimal(?curr) AS ?chg)
    }
    GROUP BY ?category
  }
  {
    SELECT ?category (AVG(xsd:decimal(?prog)) AS ?avgGoalProgressPct) (AVG(xsd:decimal(?vol)) AS ?avgVolatilityPct)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:category ?cat . }
      BIND (COALESCE(?cat, "NULL") AS ?category)
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?prog .
      ?goal wm:avgVolatilityPct ?vol .
    }
    GROUP BY ?category
  }
}

