SELECT ?riskTolGroup ?goalBucket (COUNT(?investor) AS ?investorCount)
WHERE {
  {
    SELECT ?investor ?riskTol (COUNT(?goal) AS ?goalCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:riskTolerance ?riskTol . }
      OPTIONAL {
        ?investor wm:hasInvestmentGoal ?goal .
        ?goal rdf:type wm:InvestmentGoal .
      }
    }
    GROUP BY ?investor ?riskTol
  }
  FILTER(?goalCount > 0)
  BIND(COALESCE(?riskTol, "NULL") AS ?riskTolGroup)
  BIND(
    IF(?goalCount = 1, "1",
      IF(?goalCount = 2, "2",
        IF(?goalCount = 3, "3", "4+")
      )
    ) AS ?goalBucket
  )
}
GROUP BY ?riskTolGroup ?goalBucket
ORDER BY ?riskTolGroup ?goalBucket

