SELECT DISTINCT ?investorId ?investorName
WHERE {
  {
    SELECT ?investor ?investorId
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      OPTIONAL {
        ?investor wm:riskTolerance ?rtLit .
        BIND(LCASE(STR(?rtLit)) AS ?rtLow)
      }
      OPTIONAL {
        ?investor wm:hasRiskTolerance ?rtNode .
        ?rtNode rdfs:label ?rtLabel .
        BIND(LCASE(STR(?rtLabel)) AS ?rtLow)
      }
      FILTER(BOUND(?rtLow) && CONTAINS(?rtLow, "conservative"))
    }
  }
  ?investor wm:hasPortfolioHealth ?ph .
  ?ph rdf:type wm:PortfolioHealth .
  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) < 35)

  ?investor wm:hasHolding ?holding .
  ?holding rdf:type wm:PortfolioHolding .
  ?holding wm:investmentName ?invName .
  FILTER(CONTAINS(LCASE(STR(?invName)), "gold"))

  OPTIONAL { ?investor wm:investorName ?investorName . }
}

