PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizonLabel ?avgScenarioChange ?totalScenarioChange ?scenarioCount ?avgActionChange ?totalActionChange ?actionCount
WHERE {
  {
    SELECT ?timeHorizonLabel (AVG(xsd:decimal(?scenarioChange)) AS ?avgScenarioChange) (SUM(xsd:decimal(?scenarioChange)) AS ?totalScenarioChange) (COUNT(?scenarioRebalanceId) AS ?scenarioCount)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:currentAllocationPct ?curr .
      ?sr wm:newAllocationPct ?new .
      BIND( (xsd:decimal(?new) - xsd:decimal(?curr)) AS ?scenarioChange ) .
      ?sr wm:scenarioRebalancingOfInvestor ?inv .
      ?inv rdf:type wm:Investor .
      OPTIONAL {
        ?inv wm:hasTimeHorizon ?th .
        ?th rdfs:label ?timeHorizonLabel .
      }
      BIND(COALESCE(?timeHorizonLabel, "NULL") AS ?timeHorizonLabel)
    }
    GROUP BY ?timeHorizonLabel
  }
  OPTIONAL {
    SELECT ?timeHorizonLabel (AVG(xsd:decimal(?actionChange)) AS ?avgActionChange) (SUM(xsd:decimal(?actionChange)) AS ?totalActionChange) (COUNT(?rebalanceId) AS ?actionCount)
    WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:currentAllocationPct ?currA .
      ?ra wm:targetAllocationPct ?tgt .
      BIND( (xsd:decimal(?tgt) - xsd:decimal(?currA)) AS ?actionChange ) .
      ?ra wm:rebalancingActionOfInvestor ?invA .
      ?invA rdf:type wm:Investor .
      OPTIONAL {
        ?invA wm:hasTimeHorizon ?thA .
        ?thA rdfs:label ?timeHorizonLabel .
      }
      BIND(COALESCE(?timeHorizonLabel, "NULL") AS ?timeHorizonLabel)
    }
    GROUP BY ?timeHorizonLabel
  }
}
ORDER BY ?timeHorizonLabel

