      ?ra wm:action ?action .
      FILTER(CONTAINS(LCASE(STR(?action)), "de-risk")) .
      ?ra wm:rebalancingActionOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
    }
  }
  {
