      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:hasMarketScenario ?ms .
      ?ms rdfs:label ?msLabel .
      FILTER(CONTAINS(LCASE(STR(?msLabel)), "bear market")) .
      ?sr wm:scenarioRebalancingOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
    }
  }
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }
}

