PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?goalProgress) AS ?avgGoalProgress)
       (AVG(?holdingGain) AS ?avgHoldingGain)
       (AVG(?riskScore) AS ?avgRiskScore)
       (AVG(?liquidityScore) AS ?avgLiquidityScore)
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:riskTolerance ?riskTolerance .

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?progressPct)) AS ?goalProgress)
    WHERE {
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(((xsd:decimal(?curr) - xsd:decimal(?cost)) / xsd:decimal(?cost)) * 100) AS ?holdingGain)
    WHERE {
      ?inv wm:hasHolding ?hold .
      ?hold wm:cost ?cost .
      ?hold wm:currentValue ?curr .
      FILTER(xsd:decimal(?cost) != 0)
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?riskScoreVal)) AS ?riskScore) (AVG(xsd:decimal(?liqScoreVal)) AS ?liquidityScore)
    WHERE {
      ?inv wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?riskScoreVal .
      ?ph wm:liquidityScore ?liqScoreVal .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

