SELECT ?investorId ?investorName ?totalWithdrawal
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?totalWithdrawal)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?amount .
      OPTIONAL { ?cf wm:type ?typeLiteral . }
      OPTIONAL {
        ?cf wm:hasCashFlowType ?typeObj .
        ?typeObj rdfs:label ?typeLabel .
      }
      BIND(COALESCE(?typeLiteral, ?typeLabel) AS ?typeValue)
      FILTER(BOUND(?typeValue) && LCASE(STR(?typeValue)) = "withdrawal")
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor ?riskScore
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:healthOfInvestor ?investor .
      ?ph wm:riskScore ?riskScore .
    }
  }
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
  FILTER(?avgProgress < 40)
  FILTER(xsd:decimal(?riskScore) > 50)
}
ORDER BY DESC(?totalWithdrawal)
LIMIT 5

