PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizonLabel (SUM(xsd:decimal(?cashFlowAmt)) AS ?totalCashFlow) (SUM(xsd:decimal(?scenarioChangeAmt)) AS ?totalScenarioChange) (SUM(?scenarioCount) AS ?totalScenarioCount)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:hasTimeHorizon ?timeHorizon . }
  BIND (COALESCE(?timeHorizon, "NULL") AS ?timeHorizonLabel)

