    SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?cashFlowAmt)
    WHERE {
      ?investor wm:hasCashFlow ?cf .
      ?cf rdf:type wm:CashFlow .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?allocDiff)) AS ?scenarioChangeAmt) (COUNT(?sr) AS ?scenarioCount)
    WHERE {
      ?investor wm:hasScenarioRebalancing ?sr .
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:currentAllocationPct ?curr .
      ?sr wm:newAllocationPct ?new .
      BIND (xsd:decimal(?new) - xsd:decimal(?curr) AS ?allocDiff)
    }
    GROUP BY ?investor
  }
