PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (AVG(?allocConcentration) AS ?avgAllocationConcentration)
       (AVG(?avgHoldingReturn) AS ?avgHoldingReturn)
       (AVG(?totalHoldingValue) AS ?avgHoldingValue)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:timeHorizon ?thRaw . }
  BIND(COALESCE(?thRaw, "NULL") AS ?timeHorizon)

