      ?sectorAlloc wm:allocationPct ?allocPct .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?retPct)) AS ?avgHoldingReturn) (SUM(xsd:decimal(?currVal)) AS ?totalHoldingValue)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:returnsPct ?retPct .
      ?holding wm:currentValue ?currVal .
    }
    GROUP BY ?investor
  }
}
