PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  {
    SELECT ?investor (AVG(xsd:decimal(?sharpe)) AS ?avgSharpe)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:avgSharpeRatio ?sharpe .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?vol)) AS ?avgVol)
    WHERE {
      ?goal2 rdf:type wm:InvestmentGoal .
      ?goal2 wm:belongsToInvestor ?investor .
      ?goal2 wm:avgVolatilityPct ?vol .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?curr) - xsd:decimal(?cst)) AS ?totalGain)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:currentValue ?curr .
      ?holding wm:cost ?cst .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?netCash)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?investor
  }

  FILTER(?avgSharpe < 0)
  FILTER(?avgVol > 10)
  FILTER(?totalGain < 0)
  FILTER(?netCash < 1000000)
}

