PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorLabel (COUNT(DISTINCT ?holding) AS ?completeHoldingCount)
WHERE {
  ?holding rdf:type wm:PortfolioHolding .

  OPTIONAL { ?holding wm:hasInvestmentType ?invTypeObj . }
  OPTIONAL { ?holding wm:investmentType ?invTypeLit . }

  OPTIONAL { ?holding wm:hasSector ?sectorObj . }
  OPTIONAL { ?holding wm:sector ?sectorLit . }

  OPTIONAL { ?holding wm:hasSegment ?segmentObj . }
  OPTIONAL { ?holding wm:segment ?segmentLit . }

  OPTIONAL { ?holding wm:hasCategory ?categoryObj . }
  OPTIONAL { ?holding wm:category ?categoryLit . }

  FILTER( (BOUND(?invTypeObj) || BOUND(?invTypeLit)) &&
          (BOUND(?sectorObj) || BOUND(?sectorLit)) &&
          (BOUND(?segmentObj) || BOUND(?segmentLit)) &&
          (BOUND(?categoryObj) || BOUND(?categoryLit)) )

  OPTIONAL { ?sectorObj rdfs:label ?sectorLabelObj . }

  BIND( COALESCE(?sectorLabelObj, ?sectorLit, "NULL") AS ?sectorLabel )
}
GROUP BY ?sectorLabel

