PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor ?investorName ?score
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?sf)) AS ?totalShortfall)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:shortfall ?sf .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:cost ?cost .
      ?holding wm:currentValue ?curr .
      BIND((xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?gain)
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?totalCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?rs)) AS ?riskScore)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:healthOfInvestor ?investor .
      ?ph wm:riskScore ?rs .
    }
    GROUP BY ?investor
  }

  BIND(
    (COALESCE(?totalShortfall, xsd:decimal(0))
     - COALESCE(?totalHoldingGain, xsd:decimal(0))
     - COALESCE(?totalCashFlow, xsd:decimal(0))
     + COALESCE(?riskScore, xsd:decimal(0))
    ) AS ?score)
}
ORDER BY DESC(?score)
LIMIT 10

