PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(xsd:decimal(?cashNet)) AS ?netCashFlow)
       (AVG(xsd:decimal(?goalProgress)) AS ?avgGoalProgress)
       (AVG(xsd:decimal(?goalShortfall)) AS ?avgShortfall)
WHERE {
  ?investor rdf:type wm:Investor .

  OPTIONAL { ?investor wm:category ?catLabel . }
  BIND(COALESCE(?catLabel, "NULL") AS ?category)

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?cashNet)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?goalProgress) (AVG(xsd:decimal(?shortfall)) AS ?goalShortfall)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progressPct .
      ?goal wm:shortfall ?shortfall .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?category

