  OPTIONAL { ?investor wm:investorName ?investorName . }
  OPTIONAL { ?investor wm:investmentGoal ?investmentGoal . }
  OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }
  OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }
  OPTIONAL { ?investor wm:sectorFocus ?sectorFocus . }
  OPTIONAL { ?investor wm:segment ?segment . }
  OPTIONAL { ?investor wm:category ?category . }
  FILTER (
    BOUND(?investmentGoal) && STRLEN(LCASE(STR(?investmentGoal))) > 0 &&
    BOUND(?riskTolerance) && STRLEN(LCASE(STR(?riskTolerance))) > 0 &&
