    BOUND(?sectorFocus) && STRLEN(LCASE(STR(?sectorFocus))) > 0 &&
    BOUND(?segment) && STRLEN(LCASE(STR(?segment))) > 0 &&
    BOUND(?category) && STRLEN(LCASE(STR(?category))) > 0
