PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskToleranceGroup ?cashFlowSource (COUNT(?cashflow) AS ?transactionCount)
WHERE {
  ?cashflow rdf:type wm:CashFlow .
  ?cashflow wm:cashFlowOfInvestor ?investor .
  ?investor rdf:type wm:Investor .

  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rt .
    OPTIONAL { ?rt rdfs:label ?rtLabel . }
    OPTIONAL { ?investor wm:riskTolerance ?rtLiteral . }
  }
  BIND(COALESCE(?rtLabel, ?rtLiteral, "NULL") AS ?riskToleranceGroup)

  OPTIONAL {
    ?cashflow wm:hasCashFlowSource ?source .
    OPTIONAL { ?source rdfs:label ?sourceLabel . }
  }
  BIND(COALESCE(?sourceLabel, "NULL") AS ?cashFlowSource)
}
GROUP BY ?riskToleranceGroup ?cashFlowSource

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(?cashAmt) AS ?totalCashFlow)
       (AVG(?changeAmt) AS ?avgScenarioChange)
       (SUM(?scenarioCnt) AS ?scenarioCount)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?rt . }
  BIND(COALESCE(?rt, "NULL") AS ?riskTolerance)

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?cashAmt)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?changeAmt) (COUNT(?sr) AS ?scenarioCnt)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:scenarioRebalancingOfInvestor ?investor .
      ?sr wm:newAllocationPct ?newAlloc .
      ?sr wm:currentAllocationPct ?currAlloc .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
