PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel (SUM(?holdingsPerInvestor) AS ?numHoldings) (COUNT(DISTINCT ?investor) AS ?numInvestors)
WHERE {
  ?investor rdf:type wm:Investor .

  # Determine category label (or fallback to literal category)
  OPTIONAL {
    ?investor wm:hasCategory ?cat .
    ?cat rdf:type wm:Category .
    OPTIONAL { ?cat rdfs:label ?catLabel . }
    OPTIONAL { ?investor wm:category ?catLiteral . }
    BIND (COALESCE(?catLabel, ?catLiteral, "NULL") AS ?categoryLabel)
  }
  BIND (COALESCE(?categoryLabel, "NULL") AS ?categoryLabel)

  # Count holdings per investor
  OPTIONAL {
    SELECT ?investor (COUNT(?holding) AS ?holdingsPerInvestor)
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?holding rdf:type wm:PortfolioHolding .
    } GROUP BY ?investor
  }
  BIND (COALESCE(?holdingsPerInvestor, 0) AS ?holdingsPerInvestor)
}
GROUP BY ?categoryLabel

