PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId ?investmentType ?sector ?segment ?category
WHERE {
  ?holding rdf:type wm:PortfolioHolding .
  OPTIONAL { ?holding wm:holdingId ?holdingId . }

  OPTIONAL { ?holding wm:investmentType ?investmentTypeLit . }
  OPTIONAL {
    ?holding wm:hasInvestmentType ?invType .
    ?invType rdfs:label ?investmentTypeLabel .
  }
  BIND(COALESCE(?investmentTypeLit, ?investmentTypeLabel) AS ?investmentType)

  OPTIONAL { ?holding wm:sector ?sectorLit . }
  OPTIONAL {
    ?holding wm:hasSector ?sectorObj .
    ?sectorObj rdfs:label ?sectorLabel .
  }
  BIND(COALESCE(?sectorLit, ?sectorLabel) AS ?sector)

  OPTIONAL { ?holding wm:segment ?segmentLit . }
  OPTIONAL {
    ?holding wm:hasSegment ?segmentObj .
    ?segmentObj rdfs:label ?segmentLabel .
  }
  BIND(COALESCE(?segmentLit, ?segmentLabel) AS ?segment)

  OPTIONAL { ?holding wm:category ?categoryLit . }
  OPTIONAL {
    ?holding wm:hasCategory ?catObj .
    ?catObj rdfs:label ?categoryLabel .
  }
  BIND(COALESCE(?categoryLit, ?categoryLabel) AS ?category)

  FILTER( BOUND(?investmentType) && BOUND(?sector) && BOUND(?segment) && BOUND(?category) )
}

