    ?investor wm:hasHolding ?holding .
    ?holding rdf:type wm:PortfolioHolding .
    {
      ?holding wm:hasCategory ?holdCat .
      ?holdCat rdf:type wm:Category .
      ?holdCat rdfs:label ?holdLabel .
    } UNION {
      ?holding wm:category ?holdLabel .
    }
    FILTER(CONTAINS(LCASE(STR(?holdLabel)), "debt"))
